[[|
let meta := [Reflect vtableOf: ObjectVt];
let original := [Execution directMethodFor: #addMethod in: meta];
let holder := [Object clone];
[Reflect defineMethod: #first on: holder as: [:self | 1]];
[Reflect defineMethod: #second on: holder as: [:self | 2]];
let first := [Execution directMethodFor: #first in: [Reflect vtableOf: holder]];
let second := [Execution directMethodFor: #second in: [Reflect vtableOf: holder]];
let target := [ObjectVt delegated];
let calls := [0 asCell];
let wrapper := [Reflect methodForArity: 2 implementation: [:self :key :method |
  [[key == #subscriptionProbe] ifTrue: [| [calls inc]]];
  [original invokeOn: self arguments: #[key method]]
]];
[original invokeOn: meta arguments: #[#addMethod wrapper]];
[target addMethod: first as: #subscriptionProbe];
[System println: [[calls value] = 1]];
[calls set: 0];
[original invokeOn: target arguments: #[#subscriptionProbe second]];
[System println: [[calls value] = 0]];
[System println: [[Execution directMethodFor: #subscriptionProbe in: target] == second]];
[original invokeOn: meta arguments: #[#addMethod original]]
] value]
